-- Migration: V9__seed_crawled_employers_and_skills.sql
-- Description: Seed 20 synthetic employers and 90 canonical skills from crawled IT market dataset
-- Service: occupify-identity
-- =============================================================================

-- 1. SEED 20 SYNTHETIC EMPLOYERS (users table)
ON CONFLICT (id) DO UPDATE SET
    full_name = EXCLUDED.full_name,
    avatar_url = EXCLUDED.avatar_url,
    updated_at = EXCLUDED.updated_at;

-- 2. SEED 90 CANONICAL SKILLS (skills table)
ON CONFLICT (id) DO UPDATE SET
    name = EXCLUDED.name,
    category = EXCLUDED.category;
